//! A single validated tool call; only SelectionContext is supplied as asset context.
use crate::{Res,transport::AppHandle};
use serde_json::{Value,json};

const SYSTEM:&str="你是图片批处理助手。只根据用户指令和SelectionContext选择工具，不能声称看过图片，不使用路径或猜测未提供的属性。使用execute_operations工具一次提交全部步骤，按用户顺序执行。可用：cutout抠图，white白底（包含必要的抠图），center居中，fit_ratio比例，export导出（format可选webp/png/jpeg，maxBytes是字节上限，不指定尺寸时保留当前像素），trash移入回收站，undo撤销，redo重做，generate以每张选中图为参考生成一张新场景图。generate参数prompt、ratio、orientation、resolution（默认1K、1:1横向）。保留参考产品结构、材质、颜色和文字，除非用户明确要求改动。比例只有1:1/3:2/4:3/4:5/16:9和portrait/landscape方向。未指明方向时4:5竖，其他横。未指定长边时保留当前长边，不扩大。不要用white代替cutout。不支持的识别或编辑要求只用中文说明，不调用工具；不要虚构成功，不要增加确认或预览步骤。工具参数只能有operations。";
fn request(instruction:&str,context:&Value)->Value{json!({"model":"deepseek-flash","thinking":{"type":"disabled"},"max_tokens":2000,"stream":true,"messages":[{"role":"system","content":SYSTEM},{"role":"user","content":json!({"instruction":instruction,"context":context}).to_string()}],"tools":[{"type":"function","function":{"name":"execute_operations","description":"在已确定的SelectionContext上执行图片操作","parameters":{"type":"object","required":["operations"],"additionalProperties":false,"properties":{"operations":{"type":"array","minItems":1,"maxItems":20,"items":{"type":"object","required":["kind"],"additionalProperties":false,"properties":{"kind":{"type":"string","enum":["cutout","white","center","fit_ratio","export","trash","undo","redo","generate"]},"ratio":{"type":"string","enum":["1:1","3:2","4:3","4:5","16:9"]},"orientation":{"type":"string","enum":["portrait","landscape"]},"prompt":{"type":"string"},"resolution":{"type":"string","enum":["1K","2K","4K"]},"long_edge":{"type":"integer","minimum":1,"maximum":16000},"mode":{"type":"string","enum":["auto","pad","crop"]},"format":{"type":"string","enum":["webp","png","jpeg"]},"maxBytes":{"type":"integer","minimum":0,"maximum":1000000000}}}}}}}}],"tool_choice":"auto"})}
pub(crate) async fn plan(instruction:&str,context:&Value,request_id:&str,hub:&AppHandle)->Res<Value>{
 if cfg!(test){return Err("TEST_PROVIDER_REQUIRED".into())}
 if instruction.trim().is_empty()||instruction.len()>6000{return Err("INVALID_INSTRUCTION".into())}
 let key=crate::assistant::credential()?.get_password().map_err(|_|"DEEPSEEK_KEY_REQUIRED: 请在设置中配置 DeepSeek 密钥")?;
 plan_at("https://api.deepseek.com/chat/completions",&key,instruction,context,request_id,hub).await
}
async fn plan_at(endpoint:&str,key:&str,instruction:&str,context:&Value,request_id:&str,hub:&AppHandle)->Res<Value>{let result=invoke_at(endpoint,key,&request(instruction,context),"execute_operations",request_id,hub).await?;let args=&result["arguments"];if args.is_null(){return Ok(json!({"text":result["text"],"operations":[]}))}if args.as_object().is_none_or(|map|map.len()!=1||!map.contains_key("operations")){return Err("DEEPSEEK_INVALID_TOOL_ARGUMENTS".into())}Ok(json!({"text":result["text"],"operations":args["operations"]}))}
pub(crate) async fn invoke_at(endpoint:&str,key:&str,body:&Value,expected_tool:&str,request_id:&str,hub:&AppHandle)->Res<Value>{
 let mut response=reqwest::Client::new().post(endpoint).bearer_auth(key).json(body).timeout(std::time::Duration::from_secs(60)).send().await.map_err(|_|"DEEPSEEK_NETWORK_ERROR: 未取得方案，请重试")?;
 if !response.status().is_success(){return Err(format!("DEEPSEEK_API_ERROR: HTTP {}",response.status().as_u16()))}
 let mut buffer=String::new();let mut utf8=Vec::new();let mut content=String::new();let mut name=String::new();let mut arguments=String::new();let mut finish=String::new();let mut count=0;
 while let Some(chunk)=response.chunk().await.map_err(|_|"DEEPSEEK_STREAM_INTERRUPTED")?{utf8.extend_from_slice(&chunk);if utf8.len()+buffer.len()>2*1024*1024{return Err("DEEPSEEK_RESPONSE_TOO_LARGE".into())}let valid=match std::str::from_utf8(&utf8){Ok(value)=>{let value=value.to_string();utf8.clear();value},Err(error)=>{let n=error.valid_up_to();if error.error_len().is_some(){return Err("DEEPSEEK_INVALID_UTF8".into())}let value=String::from_utf8(utf8.drain(..n).collect()).map_err(|_|"DEEPSEEK_INVALID_UTF8")?;value}};buffer.push_str(&valid);
  while let Some(index)=buffer.find('\n'){let line=buffer[..index].trim_end_matches('\r').to_string();buffer.drain(..=index);let Some(data)=line.strip_prefix("data:")else{continue};if data.trim()=="[DONE]"{continue}let value:Value=serde_json::from_str(data.trim()).map_err(|_|"DEEPSEEK_INVALID_RESPONSE")?;let choice=&value["choices"][0];if let Some(reason)=choice["finish_reason"].as_str(){finish=reason.into()}let delta=&choice["delta"];if let Some(text)=delta["content"].as_str(){content.push_str(text);hub.emit("chat.text",json!({"requestId":request_id,"delta":text}))?;}if let Some(calls)=delta["tool_calls"].as_array(){for call in calls{if call["index"].as_u64().unwrap_or(0)!=0{return Err("DEEPSEEK_MULTIPLE_TOOLS".into())}count=1;if let Some(part)=call["function"]["name"].as_str(){name.push_str(part)}if let Some(part)=call["function"]["arguments"].as_str(){arguments.push_str(part);}}}}
 }
 if !utf8.is_empty()||!buffer.trim().is_empty()||!matches!(finish.as_str(),"stop"|"tool_calls"){return Err("DEEPSEEK_INCOMPLETE_PLAN".into())}
 if count==0{return Ok(json!({"text":content,"arguments":null}))}if name!=expected_tool{return Err("DEEPSEEK_INVALID_TOOL".into())}let args:Value=serde_json::from_str(&arguments).map_err(|_|"DEEPSEEK_INVALID_TOOL_ARGUMENTS")?;Ok(json!({"text":content,"arguments":args}))
}
#[cfg(test)]mod tests{use super::*;
 #[test]fn planner_has_exactly_one_selection_context_and_no_other_asset_metadata(){let context=json!({"fileNames":["a.png"],"selected":["a"]});let body=request("居中",&context);let user:Value=serde_json::from_str(body["messages"][1]["content"].as_str().unwrap()).unwrap();assert_eq!(user,json!({"instruction":"居中","context":context}));assert!(body["tools"].is_array());assert!(!body.to_string().contains("dimensionCounts"));}
 #[tokio::test]async fn streamed_tool_call_handles_chunk_boundaries_and_emits_text_without_paid_provider(){
  use axum::{Router,routing::post,response::IntoResponse};let app=Router::new().route("/",post(||async{let chunks=[json!({"choices":[{"delta":{"content":"处理这批图片。"}}]}),json!({"choices":[{"delta":{"tool_calls":[{"index":0,"function":{"name":"execute_operations","arguments":"{\"operations\":["}}]}}]}),json!({"choices":[{"delta":{"tool_calls":[{"index":0,"function":{"arguments":"{\"kind\":\"center\"}]}"}}]},"finish_reason":"tool_calls"}]})];let body=chunks.iter().map(|v|format!("data: {v}\n\n")).collect::<String>()+"data: [DONE]\n\n";([(axum::http::header::CONTENT_TYPE,"text/event-stream")],body).into_response()}));let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let endpoint=format!("http://{}/",listener.local_addr().unwrap());let server=tokio::spawn(async move{axum::serve(listener,app).await.unwrap()});let(events,mut receiver)=tokio::sync::broadcast::channel(8);let result=plan_at(&endpoint,"fixture","居中",&json!({"fileNames":["a.png"]}),"r",&AppHandle{events}).await.unwrap();assert_eq!(result["operations"],json!([{"kind":"center"}]));assert_eq!(receiver.recv().await.unwrap()["event"],"chat.text");server.abort();
 }
}
